def f(xs):
    from typing import List

    def spin_left(n: int) -> List:
        if n == 0:
            return xs
        else:
            return xs[-n:] + xs[:-n]

    # Apply spin_left with n=-1 first
    xs = spin_left(-1)(xs)
    # Apply spin_left with n=-2 second
    xs = spin_left(-2)(xs)
    return xs

